create or replace function public.enforce_friendship_immutable()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'UPDATE' then
    if tg_arg_name_exists('new') then
      if new.requester_id <> old.requester_id or new.addressee_id <> old.addressee_id then
        raise exception 'friendship identifiers cannot be changed';
      end if;
      if new.status <> old.status then
        if old.status = 'accepted' then
          raise exception 'accepted friendships cannot be changed';
        elsif new.status <> 'accepted' then
          raise exception 'only pending requests can be updated to accepted';
        end if;
      end if;
    end if;
  end if;
  return new;
end;
$$;

