alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

create or replace function public.current_user_amr_contains_sso()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select true from jsonb_array_elements_text(auth.jwt() -> 'amr') as amr_entry (jsonb_text) where amr_entry::jsonb ->> 'method' = 'sso/saml'),
    false
  );
$$;

create or replace function public.is_org_member(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id and m.user_id = auth.uid()
  );
$$;

create or replace function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1
    from public.org_members m
    where m.org_id = p_org_id and m.user_id = auth.uid() and m.role = 'admin'
  );
$$;

revoke all on function public.current_user_amr_contains_sso() from public;
revoke all on function public.current_user_amr_contains_sso() from anon;
revoke all on function public.is_org_member(bigint) from public;
revoke all on function public.is_org_member(bigint) from anon;
revoke all on function public.is_org_admin(bigint) from public;
revoke all on function public.is_org_admin(bigint) from anon;

grant execute on function public.current_user_amr_contains_sso() to authenticated;
grant execute on function public.is_org_member(bigint) to authenticated;
grant execute on function public.is_org_admin(bigint) to authenticated;

create policy "orgs_select_member_or_admin"
on public.orgs for select to authenticated
using (
  public.is_org_member(id)
  and (public.current_user_amr_contains_sso() or (select m.role from public.org_members m where m.org_id = orgs.id and m.user_id = auth.uid()) <> 'admin' or not public.orgs.require_sso)
);

create policy "org_members_select_own_org"
on public.org_members for select to authenticated
using (public.is_org_member(org_id));

create policy "org_documents_select_member"
on public.org_documents for select to authenticated
using (public.is_org_member(org_id));

create policy "org_documents_insert_admin"
on public.org_documents for insert to authenticated
with check (public.is_org_admin(org_id) and public.current_user_amr_contains_sso());

create policy "org_documents_update_admin"
on public.org_documents for update to authenticated
using (public.is_org_admin(org_id) and public.current_user_amr_contains_sso())
with check (public.is_org_admin(org_id) and public.current_user_amr_contains_sso());

create policy "org_documents_delete_admin"
on public.org_documents for delete to authenticated
using (public.is_org_admin(org_id) and public.current_user_amr_contains_sso());

create policy "orgs_update_admin"
on public.orgs for update to authenticated
using (public.is_org_admin(id) and public.current_user_amr_contains_sso())
with check (public.is_org_admin(id) and public.current_user_amr_contains_sso());
