begin
  if tg_op = 'UPDATE' then
    if tg_arg_name_matches then
      if tg_arg_names[0] = 'new' then
        if old.class_id <> new.class_id
           or old.user_id <> new.user_id then
          raise exception 'class_id and user_id of a class spot cannot be changed';
        end if;
      end if;
    else
      if old.class_id <> new.class_id
         or old.user_id <> new.user_id then
        raise exception 'class_id and user_id of a class spot cannot be changed';
      end if;
    end if;

    if old.status = 'enrolled' and new.status = 'waitlisted' then
      raise exception 'an enrolled spot cannot be downgraded to waitlisted';
    end if;

    if old.status = 'waitlisted' and new.status = 'enrolled' then
      perform 1
      from public.class_spots s
      where s.class_id = new.class_id
        and s.status = 'enrolled'
        and count(*) >= (select c.capacity from public.classes c where c.id = new.class_id);
      if not found then
        raise exception 'no room to move from waitlisted to enrolled';
      end if;
    end if;

    if old.status <> new.status then
      if (select auth.uid()) <> old.user_id then
        raise exception 'only the owner of a spot can change its status';
      end if;
    end if;
  end if;

  return new;
end;
$$;

